output_text:
[
  {
    "id": "no_cart_in_single_file_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "shelfLinedSingleFileAisle": {
          "and": [
            "singleFileAisle",
            "adjShelf"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "shelfLinedSingleFileAisle"
        ]
      }
    }
  },
  {
    "id": "park_before_entering_single_file",
    "text": "An agent must not enter a single-file aisle while still holding the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {
        "enterSingleFileAisle": {
          "pre": {
            "not": "singleFileAisle"
          },
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "enterSingleFileAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_parking",
    "text": "If an agent parks or leaves a cart behind, they are obliged to retrieve it later before the trajectory ends.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCart": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCart",
      "discharge": "retrieveCart"
    }
  },
  {
    "id": "park_only_at_aisle_mouths",
    "text": "Carts may only be parked at designated wide aisle mouths, not arbitrarily in the store.",
    "abstraction": {
      "state_properties": {
        "parkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "wideAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        },
        "designatedCartParkingPoint": {
          "and": [
            "parkingMouth",
            "wideAisle"
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "parkCart",
          {
            "not": "designatedCartParkingPoint"
          }
        ]
      }
    }
  },
  {
    "id": "wide_shelf_pickups_require_cart",
    "text": "Shelf interactions from normal wide aisles must be performed with a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "wideShelfServicePoint": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileAisle"
            }
          ]
        }
      },
      "events": {
        "wideShelfInteraction": {
          "pre": {
            "and": [
              "INTERACT",
              "wideShelfServicePoint"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "wideShelfInteraction",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_cartless_roaming_in_open_aisles",
    "text": "Except at the entrance, cart bay, or designated parking mouths, shoppers should not roam through open aisles without a cart.",
    "abstraction": {
      "state_properties": {
        "openAisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        },
        "entranceOrCartBay": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "parkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartlessAllowedOpenPlace": {
          "or": [
            "entranceOrCartBay",
            "parkingMouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "openAisle",
          {
            "not": "hasCart"
          },
          {
            "not": "cartlessAllowedOpenPlace"
          }
        ]
      }
    }
  },
  {
    "id": "one_way_no_westbound_travel",
    "text": "Aisle traffic is one-way, so westbound travel is prohibited.",
    "abstraction": {
      "state_properties": {
        "storeAisle": "free"
      },
      "events": {
        "westboundMove": {
          "pre": "W",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "westboundMove"
    }
  },
  {
    "id": "non_shelf_interactions_only_at_cart_zones",
    "text": "Interactions away from shelves are only allowed at cart-handling zones such as the cart bay or aisle-mouth parking points.",
    "abstraction": {
      "state_properties": {
        "cartBay": "at(1,7)",
        "parkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartHandlingZone": {
          "or": [
            "cartBay",
            "parkingMouth"
          ]
        },
        "nonShelfCell": {
          "not": "adjShelf"
        }
      },
      "events": {
        "nonShelfInteraction": {
          "pre": {
            "and": [
              "INTERACT",
              "nonShelfCell"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "nonShelfInteraction",
          {
            "not": "cartHandlingZone"
          }
        ]
      }
    }
  }
]
